-- ---------------------------------------------------------------------------
-- REALINEACIÓN DE LAS SECUENCIAS DE IDENTIDAD
-- ---------------------------------------------------------------------------
-- NECESARIA y no opcional: la semilla anterior inserta identificadores explícitos y ni
-- H2 ni PostgreSQL adelantan la secuencia de identidad por esa vía. Sin esto, la primera
-- cita o disponibilidad que la aplicación cree al vuelo recibiría el identificador 1 y
-- chocaría contra la clave primaria de la fila sembrada.
ALTER TABLE eps ALTER COLUMN id RESTART WITH 4;
ALTER TABLE ips ALTER COLUMN id RESTART WITH 4;
ALTER TABLE eps_ips ALTER COLUMN id RESTART WITH 6;
ALTER TABLE usuarios ALTER COLUMN id RESTART WITH 7;
ALTER TABLE especialidades ALTER COLUMN id RESTART WITH 6;
ALTER TABLE medicos ALTER COLUMN id RESTART WITH 3;
ALTER TABLE disponibilidades_medicas ALTER COLUMN id RESTART WITH 6;
ALTER TABLE citas ALTER COLUMN id RESTART WITH 1;
ALTER TABLE colas_espera ALTER COLUMN id RESTART WITH 1;
ALTER TABLE historias_clinicas ALTER COLUMN id RESTART WITH 2;
ALTER TABLE autorizaciones_acceso ALTER COLUMN id RESTART WITH 2;
ALTER TABLE notificaciones ALTER COLUMN id RESTART WITH 1;
ALTER TABLE eps_affiliates ALTER COLUMN id RESTART WITH 7;
ALTER TABLE sedes ALTER COLUMN id RESTART WITH 7;
ALTER TABLE servicios ALTER COLUMN id RESTART WITH 13;
ALTER TABLE medico_servicios ALTER COLUMN id RESTART WITH 7;
ALTER TABLE bloques_disponibilidad ALTER COLUMN id RESTART WITH 1;
